insert into public.about_sections (id, content, enabled, sort_order) values ('header','{"title": "About Kovo", "intro": "Bags and accessories for everyday life, delivered across Bangladesh."}'::jsonb,true,0);
insert into public.about_sections (id, content, enabled, sort_order) values ('story','{"headline": "Our story", "text": "Kovo started with a simple idea: good bags and accessories should be easy to buy, fairly priced and delivered to your door.\n\nWe choose every handbag, backpack, wallet and accessory for how it looks, how it is made and how well it holds up to daily use.", "image": "https://images.unsplash.com/photo-1483985988355-763728e1935b?w=1200&h=900&fit=crop&auto=format&q=80"}'::jsonb,true,1);
insert into public.about_sections (id, content, enabled, sort_order) values ('mission_vision','{"mission": "Make well-made bags and accessories easy to find and easy to buy anywhere in Bangladesh.", "vision": "To be the first place people in Bangladesh look for everyday bags and accessories."}'::jsonb,true,2);
